<script setup>
import { computed, onBeforeUnmount, ref, watch } from "vue";
import { useRoute } from "vue-router";
import ErrorState from "@/components/feedback/ErrorState.vue";
import PermissionDenied from "@/components/feedback/PermissionDenied.vue";
import PageContainer from "@/components/layout/PageContainer.vue";
import { getReportDefinition, runReport } from "@/services/universal.js";
const route = useRoute(); const definition = ref(null); const result = ref(null); const filtersText = ref("{}"); const loading = ref(true); const error = ref(null); let controller;
const feature = computed(() => String(route.params.report));
async function load() { controller?.abort(); controller = new AbortController(); loading.value = true; error.value = null; try { definition.value = await getReportDefinition(feature.value, controller.signal); } catch (caught) { if (caught.name !== "AbortError") error.value = caught; } finally { loading.value = false; } }
async function run() { loading.value = true; error.value = null; try { result.value = await runReport(feature.value, JSON.parse(filtersText.value || "{}")); } catch (caught) { error.value = caught instanceof SyntaxError ? new Error("Filters must be valid JSON.") : caught; } finally { loading.value = false; } }
watch(feature, load, { immediate: true }); onBeforeUnmount(() => controller?.abort());
</script>
<template><PageContainer><PermissionDenied v-if="error?.permissionDenied" /><ErrorState v-else-if="error && !definition" title="Unable to load report" :message="error.message" /><section v-else class="ru-page"><header class="ru-page__header"><div><span class="ru-eyebrow">UNIVERSAL REPORT ENGINE · PROVISIONAL</span><h1>{{ definition?.name || 'Report' }}</h1><p>{{ definition?.report_type }} · {{ definition?.reference_doctype }}</p></div><button class="ref-button ref-button--primary" type="button" :disabled="loading" @click="run">{{ loading ? 'Running…' : 'Run report' }}</button></header><section class="ru-card"><h2>Report filters</h2><p>Enter only filters supported by this installed report. A metadata filter adapter is still required for reports whose filters are defined in Client Script.</p><textarea v-model="filtersText" rows="5" aria-label="Report filters as JSON" style="width:100%" /></section><div v-if="error" class="ru-validation" role="alert">{{ error.message }}</div><div v-if="result?.columns?.length" class="ru-table-wrap"><table><thead><tr><th v-for="column in result.columns" :key="column.fieldname">{{ column.label || column.fieldname }}</th></tr></thead><tbody><tr v-for="(row,index) in result.result" :key="index"><td v-for="column in result.columns" :key="column.fieldname" :data-label="column.label || column.fieldname">{{ row[column.fieldname] ?? '—' }}</td></tr></tbody></table></div><div v-else-if="result" class="ru-empty">The report returned no rows.</div><section v-if="result?.chart" class="ru-card"><h2>Chart data</h2><p>A specialised chart renderer is required for this report. The server result has been preserved.</p></section></section></PageContainer></template>
